def is_grammar_category(category_key):
    return category_key in GRAMMAR_CATEGORIES


def grammar_pairs(category_key, source_language, target_language):
    """
    The pairs for one grammar category in one target language, in the app's
    own pair shape: the word is the target ("target word") and its grammatical
    label, written in the learner's native (source) language, is the source
    ("source word"). Returns None if this category
    has no table for that language (the caller decides how to report that).
    """
    rows = GRAMMAR_CATEGORIES.get(category_key, {}).get(target_language)
    if rows is None:
        return None
    pairs = []
    for row in rows:
        word, kind, tags, meanings = row
        label = render_label(source_language, kind, tags, meanings.get(source_language))
        pairs.append({"source word": label, "target word": word})
    return pairs
